(6762136, 1012883, 94265, '<td valign="top">I =wish the lighthouse wasn''t so centred but the central position kinda fits with the title, it''s a pretty image regardless, lovely sky.</td>', 'I =wish the lighthouse wasn''t so centred but the central position kinda fits with the title, it''s a pretty image regardless, lovely sky.', '2012-05-07 14:39:59.000000', NULL, 1),
(6762137, 1012489, 94265, '<td valign="top">Lots of nice greenery but the sky looks a bit like you''ve burned it like crazy or something, which spoils it a bit for me. Overall the brightness just doesn''t seem strong enough.</td>', 'Lots of nice greenery but the sky looks a bit like you''ve burned it like crazy or something, which spoils it a bit for me. Overall the brightness just doesn''t seem strong enough.', '2012-05-07 14:41:12.000000', NULL, 1),
(6762138, 1011879, 94265, '<td valign="top">Quite a nice high-key edit, the image looks perhaps a wee bit soft to me but I like the simplicity.</td>', 'Quite a nice high-key edit, the image looks perhaps a wee bit soft to me but I like the simplicity.', '2012-05-07 14:42:01.000000', NULL, 1),
(6762139, 1012600, 94265, '<td valign="top">A very nicely taken portrait; I''m not a fan of the removal of eye veins personally as I think it makes eyes look a bit odd but overall, the image is pretty and the lighting is spot-on.</td>', 'A very nicely taken portrait; I''m not a fan of the removal of eye veins personally as I think it makes eyes look a bit odd but overall, the image is pretty and the lighting is spot-on.', '2012-05-07 14:43:54.000000', NULL, 1),
(6762140, 1011850, 94265, '<td valign="top">I understand the soft, hazy edit in relation to the title but I think I''d prefer this to have been in a crisp, clearer state. Maybe because the subject of the image isn''t very dreamlike to me, I''m not sure. Composition is good.</td>', 'I understand the soft, hazy edit in relation to the title but I think I''d prefer this to have been in a crisp, clearer state. Maybe because the subject of the image isn''t very dreamlike to me, I''m not sure. Composition is good.', '2012-05-07 14:46:07.000000', NULL, 1),
(6762142, 1013002, 94265, '<td valign="top">This made me laugh, very cute and nicely taken, good focus on his nose and the glasses.</td>', 'This made me laugh, very cute and nicely taken, good focus on his nose and the glasses.', '2012-05-07 14:46:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6762143, 1012845, 94265, '<td valign="top">Beautiful horse, nice setting. The reflection almost looks like a different time of day, give this an interesting effect.</td>', 'Beautiful horse, nice setting. The reflection almost looks like a different time of day, give this an interesting effect.', '2012-05-07 14:48:00.000000', NULL, 1),
(6762144, 1012170, 94265, '<td valign="top">I''m not quite sure I get it, the man doesn''t look like your typical acoustic guitar guy, lol. It''s a well-taken and well-lit image anyway though, I''d so love to shoot a model in that room!</td>', 'I''m not quite sure I get it, the man doesn''t look like your typical acoustic guitar guy, lol. It''s a well-taken and well-lit image anyway though, I''d so love to shoot a model in that room!', '2012-05-07 14:49:19.000000', NULL, 1),
(6762145, 1012397, 54446, '<td valign="top">This is excellent  Love the light.  Sadly, you felt a need to mark it as "autumn" and "Southern Hemisphere".  It''s a strong enough image to stand on its own without trying to explain in the title.  Ignoring the title, 9.</td>', 'This is excellent  Love the light.  Sadly, you felt a need to mark it as "autumn" and "Southern Hemisphere".  It''s a strong enough image to stand on its own without trying to explain in the title.  Ignoring the title, 9.', '2012-05-07 14:49:51.000000', NULL, 1),
(6762146, 1012747, 94265, '<td valign="top">She sure looks fed up, haha. Very nice capture of a beautiful animal.</td>', 'She sure looks fed up, haha. Very nice capture of a beautiful animal.', '2012-05-07 14:50:09.000000', NULL, 1),
(6762147, 1011377, 94265, '<td valign="top">An unusual angle for this sort of shot, I quite like it, it lets us see the cuteness of the little one in full; love those little feet! I don''t think the mat underneath the basket was needed but that''s a small niggle. Nice exposure and focus too, well done.</td>', 'An unusual angle for this sort of shot, I quite like it, it lets us see the cuteness of the little one in full; love those little feet! I don''t think the mat underneath the basket was needed but that''s a small niggle. Nice exposure and focus too, well done.', '2012-05-07 14:52:57.000000', NULL, 1),
(6762148, 1009876, 54446, '<td valign="top">Beautiful!  Great luminous glow and spectacular sky.  I might have moved the wonderful boats off of dead center, but that''s just a minor nitpick.  10</td>', 'Beautiful!  Great luminous glow and spectacular sky.  I might have moved the wonderful boats off of dead center, but that''s just a minor nitpick.  10', '2012-05-07 14:53:17.000000', NULL, 1),
(6762149, 1011349, 94265, '<td valign="top">I don''t find this a particularly interesting subject personally but it''s a well-taken shot, good exposure.</td>', 'I don''t find this a particularly interesting subject personally but it''s a well-taken shot, good exposure.', '2012-05-07 14:53:39.000000', NULL, 1),
(6762151, 1010748, 94265, '<td valign="top">Lovely scenery, the light and sky are very dramatic.</td>', 'Lovely scenery, the light and sky are very dramatic.', '2012-05-07 14:54:03.000000', NULL, 1),
(6762152, 1011419, 94265, '<td valign="top">The crop feels a little tight, not a big issue though. I just wish we could see the little one playing with it, to add a bit more interest. Nice sharp focus on the hat.</td>', 'The crop feels a little tight, not a big issue though. I just wish we could see the little one playing with it, to add a bit more interest. Nice sharp focus on the hat.', '2012-05-07 14:55:13.000000', NULL, 1),
(6762156, 1013003, 94265, '<td valign="top">Always good to see an unusual subject. Saturation looks a little strong.</td>', 'Always good to see an unusual subject. Saturation looks a little strong.', '2012-05-07 14:56:50.000000', NULL, 1),
(6762158, 1011777, 94265, '<td valign="top">Very peaceful.</td>', 'Very peaceful.', '2012-05-07 14:57:20.000000', NULL, 1),
(6762160, 1011246, 94265, '<td valign="top">Lovely colours, nice strong bokeh, great focus on the petals. Just gorgeous!</td>', 'Lovely colours, nice strong bokeh, great focus on the petals. Just gorgeous!', '2012-05-07 14:58:10.000000', NULL, 1),
(6762162, 1012138, 94265, '<td valign="top">Beautiful place, nice vantage point. The cyan saturation looks a bit too strong.</td>', 'Beautiful place, nice vantage point. The cyan saturation looks a bit too strong.', '2012-05-07 14:58:53.000000', NULL, 1),
(6762163, 1011612, 94265, '<td valign="top">Perhaps not quite interesting enough a subject to be filling the entire frame but the exposure is good, nice sharp focus and good bokeh in the back.</td>', 'Perhaps not quite interesting enough a subject to be filling the entire frame but the exposure is good, nice sharp focus and good bokeh in the back.', '2012-05-07 14:59:40.000000', NULL, 1),
(6762164, 1012750, 94265, '<td valign="top">I''d like this better if his nose had been wiped first, lol. Nice angle, lovely big eyes. Could be a little brighter overall.</td>', 'I''d like this better if his nose had been wiped first, lol. Nice angle, lovely big eyes. Could be a little brighter overall.', '2012-05-07 15:01:28.000000', NULL, 1),
(6762165, 1011970, 94265, '<td valign="top">Very nicely-taken night shot, good exposure and composition.</td>', 'Very nicely-taken night shot, good exposure and composition.', '2012-05-07 15:01:52.000000', NULL, 1),
(6762169, 1011042, 94265, '<td valign="top">Nice sharp focus, beautiful animal. Are those branches on the left there? Their dark form is a bit distracting against the light white subject, I might have tried to find a different vantage point that didn''t include them if possible.</td>', 'Nice sharp focus, beautiful animal. Are those branches on the left there? Their dark form is a bit distracting against the light white subject, I might have tried to find a different vantage point that didn''t include them if possible.', '2012-05-07 15:03:23.000000', NULL, 1),
(6762171, 1012364, 94265, '<td valign="top">Very sweet image.</td>', 'Very sweet image.', '2012-05-07 15:03:42.000000', NULL, 1),
(6762172, 1012350, 94265, '<td valign="top">Nice sharp action shot, contrast is maybe a tad too light.</td>', 'Nice sharp action shot, contrast is maybe a tad too light.', '2012-05-07 15:04:11.000000', NULL, 1),
(6762173, 1008530, 94265, '<td valign="top">Good composition, I like the idea, very cool.</td>', 'Good composition, I like the idea, very cool.', '2012-05-07 15:04:38.000000', NULL, 1),
(6762174, 1012436, 94265, '<td valign="top">I wish there was just a little bit more in focus, would''ve made this much better for me personally. I don''t care for the side borders. Nice subject and light though.</td>', 'I wish there was just a little bit more in focus, would''ve made this much better for me personally. I don''t care for the side borders. Nice subject and light though.', '2012-05-07 15:05:50.000000', NULL, 1),
(6762176, 1012088, 94265, '<td valign="top">A few specks that could''ve been cloned away, I''m a bit of a stickler about wrinkles/creases in material too but the set-up is good, very nice lighting, lovely model.</td>', 'A few specks that could''ve been cloned away, I''m a bit of a stickler about wrinkles/creases in material too but the set-up is good, very nice lighting, lovely model.', '2012-05-07 15:07:07.000000', NULL, 1),
(6762177, 1012460, 94265, '<td valign="top">Good focus and bokeh.</td>', 'Good focus and bokeh.', '2012-05-07 15:07:23.000000', NULL, 1),
(6762178, 1009129, 94265, '<td valign="top">I appreciate the kind of shot you''ve tried to achieve here (and it''s not easy to get such a close macro of bugs!) but there seems to be quite a lot of quality lost. It''s very smooth in places and noisy in others. Shame, as the exposure, composition and colours look Ok.</td>', 'I appreciate the kind of shot you''ve tried to achieve here (and it''s not easy to get such a close macro of bugs!) but there seems to be quite a lot of quality lost. It''s very smooth in places and noisy in others. Shame, as the exposure, composition and colours look Ok.', '2012-05-07 15:09:55.000000', NULL, 1),
(6762179, 1008110, 94265, '<td valign="top">My nightmare is so much noise, lol. I like the idea but the grain obscures this an annoying amount; that thing beside him could be a pile of garbage, a big rock or a baby dragon for all I know. I don''t personally find this engaging enough to draw me in.</td>', 'My nightmare is so much noise, lol. I like the idea but the grain obscures this an annoying amount; that thing beside him could be a pile of garbage, a big rock or a baby dragon for all I know. I don''t personally find this engaging enough to draw me in.', '2012-05-07 15:12:20.000000', NULL, 1),
(6762180, 1009589, 94265, '<td valign="top">Pretty image, I like an exposure where you can still see some water detail without it looking like pure white fog.</td>', 'Pretty image, I like an exposure where you can still see some water detail without it looking like pure white fog.', '2012-05-07 15:13:45.000000', NULL, 1),
(6762181, 1012451, 94265, '<td valign="top">Lovely tones and great focus, very nice image.</td>', 'Lovely tones and great focus, very nice image.', '2012-05-07 15:14:00.000000', NULL, 1),
(6762182, 1012200, 94265, '<td valign="top">I love the composition and the colours, pretty light too. Nice work.</td>', 'I love the composition and the colours, pretty light too. Nice work.', '2012-05-07 15:14:27.000000', NULL, 1),
(6762183, 1010843, 94265, '<td valign="top">Seeing more of his eyes would make this more engaging but this is a good candid street shot, good exposure and focus.</td>', 'Seeing more of his eyes would make this more engaging but this is a good candid street shot, good exposure and focus.', '2012-05-07 15:17:52.000000', NULL, 1),
(6762184, 1011942, 94265, '<td valign="top">Very pretty and nice bokeh.</td>', 'Very pretty and nice bokeh.', '2012-05-07 15:18:09.000000', NULL, 1),
(6762185, 1011173, 94265, '<td valign="top">I like the vibrancy, a nice scene, it''s like something from the postcard of a quaint little town.</td>', 'I like the vibrancy, a nice scene, it''s like something from the postcard of a quaint little town.', '2012-05-07 15:19:07.000000', NULL, 1),
(6762187, 1012691, 94265, '<td valign="top">Good exposure. An intriguing image, makes me want to know what''s going on.</td>', 'Good exposure. An intriguing image, makes me want to know what''s going on.', '2012-05-07 15:20:26.000000', NULL, 1),
(6762188, 1012427, 94265, '<td valign="top">I like this perspective.</td>', 'I like this perspective.', '2012-05-07 15:20:52.000000', NULL, 1),
(6762190, 1011417, 94265, '<td valign="top">Highlights are a bit harsh but the body painting is pretty cool, good work there. Nice colours.</td>', 'Highlights are a bit harsh but the body painting is pretty cool, good work there. Nice colours.', '2012-05-07 15:21:34.000000', NULL, 1),
(6762191, 1011923, 94265, '<td valign="top">Lovely shot, great composition and bokeh.</td>', 'Lovely shot, great composition and bokeh.', '2012-05-07 15:22:14.000000', NULL, 1),
(6762193, 1012884, 54446, '<td valign="top">Very nice tree swallows.  I especially like the captured behavior of this pleasant species.  10</td>', 'Very nice tree swallows.  I especially like the captured behavior of this pleasant species.  10', '2012-05-07 15:23:38.000000', NULL, 1),
(6762194, 1011982, 94265, '<td valign="top">This is a really lovely image, the little one''s expression is fantastic. I find my eyes drawn quite a bit to the spade card design on the man''s shirt though since it''s right in the line of sight between their gaze, I''d have got him to wear something a little more plain. I''m giving this an 8 as it''s great otherwise, just wish his shirt just had the simple stripes.</td>', 'This is a really lovely image, the little one''s expression is fantastic. I find my eyes drawn quite a bit to the spade card design on the man''s shirt though since it''s right in the line of sight between their gaze, I''d have got him to wear something a little more plain. I''m giving this an 8 as it''s great otherwise, just wish his shirt just had the simple stripes.', '2012-05-07 15:26:13.000000', NULL, 1),
(6762195, 1009379, 54446, '<td valign="top">Love the bleach bypass look here.  Superb surreal look.  10</td>', 'Love the bleach bypass look here.  Superb surreal look.  10', '2012-05-07 15:26:14.000000', NULL, 1),
(6762197, 1012399, 94265, '<td valign="top">Unbelievably cute, look at that wee face and  that floppy ear! SQUEE. Cute title too. Well done.</td>', 'Unbelievably cute, look at that wee face and  that floppy ear! SQUEE. Cute title too. Well done.', '2012-05-07 15:26:49.000000', NULL, 1),
(6762198, 1010585, 54446, '<td valign="top">Great capture of the Great Blue.9</td>', 'Great capture of the Great Blue.9', '2012-05-07 15:27:06.000000', NULL, 1),
(6762200, 1012450, 94265, '<td valign="top">Great portrait, very moody, excellent lighting and a really good model.</td>', 'Great portrait, very moody, excellent lighting and a really good model.', '2012-05-07 15:27:23.000000', NULL, 1),
(6762202, 1012170, 54446, '<td valign="top">Really a pleasant and interesting image.  Pro quality through and through.  9</td>', 'Really a pleasant and interesting image.  Pro quality through and through.  9', '2012-05-07 15:27:59.000000', NULL, 1),
(6762203, 1008730, 94265, '<td valign="top">This is gorgeous, love the way the light hits the water and the bird, an excellent capture.</td>', 'This is gorgeous, love the way the light hits the water and the bird, an excellent capture.', '2012-05-07 15:28:00.000000', NULL, 1),
(6762204, 1012350, 54446, '<td valign="top">Sports Illustrated quality.  Nice action capture.  You''ve captured the intensity and focus.  9</td>', 'Sports Illustrated quality.  Nice action capture.  You''ve captured the intensity and focus.  9', '2012-05-07 15:29:15.000000', NULL, 1),
(6762205, 1012387, 94265, '<td valign="top">This is great, a nice fun shot, lovely green eyes and freckles. Looks like she''s at work or something? The bokeh is perfect as it blurs what I think would be a distracting background.</td>', 'This is great, a nice fun shot, lovely green eyes and freckles. Looks like she''s at work or something? The bokeh is perfect as it blurs what I think would be a distracting background.', '2012-05-07 15:29:50.000000', NULL, 1),
(6762206, 1013003, 54446, '<td valign="top">Amazing capture.  Much fun to view and study.  10</td>', 'Amazing capture.  Much fun to view and study.  10', '2012-05-07 15:30:01.000000', NULL, 1),
(6762208, 1009947, 54446, '<td valign="top">Striking.  10</td>', 'Striking.  10', '2012-05-07 15:30:53.000000', NULL, 1),
(6762236, 1011496, 138253, '<td valign="top">I thought male genetalia was not permitted in photos.... (you''re holding your ****) ;)</td>', 'I thought male genetalia was not permitted in photos.... (you''re holding your ****) ;)', '2012-05-07 16:19:06.000000', NULL, 1),
(6762247, 1012845, 56502, '<td valign="top">Great catch with it being completely in the air.</td>', 'Great catch with it being completely in the air.', '2012-05-07 16:33:50.000000', NULL, 1),
(6762248, 1012941, 56502, '<td valign="top">Great colors.</td>', 'Great colors.', '2012-05-07 16:34:17.000000', NULL, 1),
(6762250, 1012930, 56502, '<td valign="top">Amazing pose - and she even looks relatively relaxed ...</td>', 'Amazing pose - and she even looks relatively relaxed ...', '2012-05-07 16:36:24.000000', NULL, 1),
(6762251, 1011033, 56502, '<td valign="top">Fascinating detail.</td>', 'Fascinating detail.', '2012-05-07 16:38:13.000000', NULL, 1),
(6762330, 1012782, 67258, '<td valign="top">Superb!</td>', 'Superb!', '2012-05-07 18:18:34.000000', NULL, 1),
(6762351, 1011897, 65234, '<td valign="top">Love the sun zigzagging through the water.</td>', 'Love the sun zigzagging through the water.', '2012-05-07 18:31:12.000000', NULL, 1),
(6762355, 1011879, 65234, '<td valign="top">Lovely simplicity to this scene.</td>', 'Lovely simplicity to this scene.', '2012-05-07 18:32:11.000000', NULL, 1),
(6762359, 1012864, 65234, '<td valign="top">Puffins are so cute!  This one looks a little on the uncoordinated side, which is just endearing :-)</td>', 'Puffins are so cute!  This one looks a little on the uncoordinated side, which is just endearing :-)', '2012-05-07 18:34:39.000000', NULL, 1),
(6762362, 1011859, 65234, '<td valign="top">Love the birds in the mist.  Nice composition and mood. I might desaturate the yellow I''m seeing at the bottom of the image.</td>', 'Love the birds in the mist.  Nice composition and mood. I might desaturate the yellow I''m seeing at the bottom of the image.', '2012-05-07 18:36:19.000000', NULL, 1),
(6762377, 1011246, 65234, '<td valign="top">Love the light and bokeh.</td>', 'Love the light and bokeh.', '2012-05-07 18:46:31.000000', NULL, 1),
(6762381, 1012845, 65234, '<td valign="top">Gorgeous light!  Just magical :-)</td>', 'Gorgeous light!  Just magical :-)', '2012-05-07 18:47:26.000000', NULL, 1),
(6762384, 1012950, 65234, '<td valign="top">Oh, dear.  I don''t expect to see a rider quite that vertical =:-o</td>', 'Oh, dear.  I don''t expect to see a rider quite that vertical =:-o', '2012-05-07 18:50:16.000000', NULL, 1),
(6762389, 1012945, 65234, '<td valign="top">O.M.G.  That looks really painful.</td>', 'O.M.G.  That looks really painful.', '2012-05-07 18:53:44.000000', NULL, 1),
(6762390, 1012886, 65234, '<td valign="top">Beautifully lit and I love the concentration in her expression.  Looks a bit young for toe shoes ;-)</td>', 'Beautifully lit and I love the concentration in her expression.  Looks a bit young for toe shoes ;-)', '2012-05-07 18:54:51.000000', NULL, 1),
(6762412, 1012239, 117717, '<td valign="top">Wonderful setting &amp; mood.</td>', 'Wonderful setting & mood.', '2012-05-07 19:20:03.000000', NULL, 1),
(6762415, 1011910, 117717, '<td valign="top">Charming image, makes the everyday look extra-ordinary!</td>', 'Charming image, makes the everyday look extra-ordinary!', '2012-05-07 19:22:19.000000', NULL, 1),
(6762416, 1012820, 117717, '<td valign="top">Love this- one of my favourite''s of the challenge.  Beautiful lighting!</td>', 'Love this- one of my favourite''s of the challenge.  Beautiful lighting!', '2012-05-07 19:24:20.000000', NULL, 1),
(6762417, 1012878, 120171, '<td valign="top">I really like the mysticism feeling the shot portrays but my eye was drawn to Excalibur''s sword coming out of the sea (just to the right of the sun)</td>', 'I really like the mysticism feeling the shot portrays but my eye was drawn to Excalibur''s sword coming out of the sea (just to the right of the sun)', '2012-05-07 19:24:22.000000', NULL, 1),
(6762419, 1010748, 117717, '<td valign="top">Great detail &amp; vibrancy- those mountains look imposing!</td>', 'Great detail & vibrancy- those mountains look imposing!', '2012-05-07 19:25:34.000000', NULL, 1),
(6762425, 1012336, 117717, '<td valign="top">Bump to a 10- that eye is mesmerizing.  Love that you captured some motion here.  Stunning image!</td>', 'Bump to a 10- that eye is mesmerizing.  Love that you captured some motion here.  Stunning image!', '2012-05-07 19:28:07.000000', NULL, 1),
(6762427, 1012451, 117717, '<td valign="top">The textures are wonderful, a beautiful b&amp;w image.</td>', 'The textures are wonderful, a beautiful b&w image.', '2012-05-07 19:30:15.000000', NULL, 1),
(6762428, 1013002, 117717, '<td valign="top">Not only fun, but also mysteriously compelling...I want to learn more about this Professor Pooka!  Well done :)</td>', 'Not only fun, but also mysteriously compelling...I want to learn more about this Professor Pooka!  Well done :)', '2012-05-07 19:32:41.000000', NULL, 1),
(6762430, 1012426, 117717, '<td valign="top">Gorgeous lighting!</td>', 'Gorgeous lighting!', '2012-05-07 19:33:21.000000', NULL, 1),
(6762435, 1009876, 117717, '<td valign="top">That sky is amazing. I love that you broke the rules (centred horizon &amp; subjects dead centre) and made an exceptional image!  Also love  the way the clouds in the sky &amp; in the reflection lead my eye to the boats.  I just want to relax with a good book in one!</td>', 'That sky is amazing. I love that you broke the rules (centred horizon & subjects dead centre) and made an exceptional image!  Also love  the way the clouds in the sky & in the reflection lead my eye to the boats.  I just want to relax with a good book in one!', '2012-05-07 19:41:04.000000', NULL, 1),
(6762437, 1010872, 117717, '<td valign="top">Great textures, love the composition &amp; exposure.</td>', 'Great textures, love the composition & exposure.', '2012-05-07 19:43:54.000000', NULL, 1),
(6762438, 1012069, 117717, '<td valign="top">Wonderful spontaneity &amp; beautiful light.</td>', 'Wonderful spontaneity & beautiful light.', '2012-05-07 19:47:07.000000', NULL, 1),
(6762440, 1009876, 120171, '<td valign="top">Bold composition, fantastic colours and symmetry. Got to be top 3. 10</td>', 'Bold composition, fantastic colours and symmetry. Got to be top 3. 10', '2012-05-07 19:48:34.000000', NULL, 1),
(6762442, 1012888, 117717, '<td valign="top">Terrific light &amp; vibrancy.</td>', 'Terrific light & vibrancy.', '2012-05-07 19:48:43.000000', NULL, 1),
(6762446, 1012775, 117717, '<td valign="top">Like the sharpness of the barns against the softness of the cloudy sky.  Beautiful composition.</td>', 'Like the sharpness of the barns against the softness of the cloudy sky.  Beautiful composition.', '2012-05-07 19:50:37.000000', NULL, 1),
(6762447, 1012775, 120171, '<td valign="top">I really like the processing here, it has a haunting feel to it. Hope to see this on the front tomorrow. 10</td>', 'I really like the processing here, it has a haunting feel to it. Hope to see this on the front tomorrow. 10', '2012-05-07 19:50:42.000000', NULL, 1),
(6762449, 1010746, 120171, '<td valign="top">No prizes for guessing who this is by.<br/> <br/>Thoughtful image. I particularly like the lens flare of the windscreen.<br/> <br/>Got to be in the top 3. 10</td>', 'No prizes for guessing who this is by. Thoughtful image. I particularly like the lens flare of the windscreen. Got to be in the top 3. 10', '2012-05-07 19:50:57.000000', NULL, 1),
