(6762454, 1012921, 76335, '<td valign="top">Silent rhythm. Nice.</td>', 'Silent rhythm. Nice.', '2012-05-07 19:54:09.000000', NULL, 1),
(6762455, 1012387, 10785, '<td valign="top">Super sharp with great skin tones in the color processing. I like the environmental portrait and think that you could have used a little smaller aperture to get more of that environment to show through.</td>', 'Super sharp with great skin tones in the color processing. I like the environmental portrait and think that you could have used a little smaller aperture to get more of that environment to show through.', '2012-05-07 19:54:10.000000', NULL, 1),
(6762457, 1012820, 76335, '<td valign="top">Very metallic. I''m reminded of clawmarks. Great.</td>', 'Very metallic. I''m reminded of clawmarks. Great.', '2012-05-07 19:55:07.000000', NULL, 1),
