(6765038, 1011295, 91496, '<td valign="top">You was robbed -- I had this as a ribbon winner.  I love that it uses HDR to improve the photo, not to distort reality.</td>', 'You was robbed -- I had this as a ribbon winner.  I love that it uses HDR to improve the photo, not to distort reality.', '2012-05-09 19:35:15.000000', NULL, 0),
(6765065, 1012608, 136235, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by markwiley:</b></div><hr/><i> I just noticed, if I would have gotten to this in voting and given it the vote it deserved you probably would have passed that kid who got 95th. </i></td></tr></table> lol! Thanks for the comment-- means a lot.</td>', 'Originally posted by markwiley: I just noticed, if I would have gotten to this in voting and given it the vote it deserved you probably would have passed that kid who got 95th.  lol! Thanks for the comment-- means a lot.', '2012-05-09 20:31:11.000000', NULL, 0),
